<?php

namespace App\Services\Invoices;

use App\Models\InvoicePreparation;
use DOMDocument;
use DOMElement;
use DomainException;

/**
 * Unsigned test candidate for ordinary Turkish e-Invoice sales, based on
 * EDM supplied satis_temel.xml and satis_ticari.xml. No network, storage,
 * fiscal number allocation, or public/admin export route. Synthetic ordinary
 * examples passed pinned GIB XSD and Schematron CI; this is NOT fiscal
 * approval or validation of arbitrary generated bytes. Must not be submitted.
 */
final class UblSaleCandidate
{
    private const INV='urn:oasis:names:specification:ubl:schema:xsd:Invoice-2';
    private const CAC='urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2';
    private const CBC='urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2';
    private const EXT='urn:oasis:names:specification:ubl:schema:xsd:CommonExtensionComponents-2';
    private const UNSIGNED='urn:newtic:unsigned-candidate:1';
    public const EDM_SERIAL_SENTINEL='ABC2009123456789';

    public function __construct(private InvoicePreparationXml $components) {}

    private function node(DOMElement $parent,string $prefix,string $name,?string $value=null): DOMElement
    {
        $node=$parent->appendChild($parent->ownerDocument->createElementNS($prefix==='cac' ? self::CAC : self::CBC,$prefix.':'.$name));
        if ($value!==null) $node->appendChild($parent->ownerDocument->createTextNode($value));
        return $node;
    }

    private function field(array $data,string $key,int $max=255): string
    {
        $value=$data[$key] ?? null;
        if (!is_string($value) || trim($value)==='' || mb_strlen($value)>$max
            || !preg_match('/^[\x{20}-\x{D7FF}\x{E000}-\x{FFFD}\x{10000}-\x{10FFFF}\t\r\n]+$/uD',$value)) {
            throw new DomainException('Eksik veya geçersiz belge alanı: '.$key);
        }
        return trim($value);
    }

    private function date(string $date): string
    {
        if (!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D',$date,$m) || !checkdate((int)$m[2],(int)$m[3],(int)$m[1])) {
            throw new DomainException('Geçersiz belge tarihi.');
        }
        return $date;
    }

    private function party(DOMElement $root,string $type,array $data,bool $allowAnonymous=false): void
    {
        $identifier=$this->field($data,'identifier',11);
        if (!preg_match('/^[0-9]{10,11}$/D',$identifier) || ($identifier==='11111111111' && !$allowAnonymous)) {
            throw new DomainException('e-Fatura için geçerli taraf kimlik bilgisi gerekiyor.');
        }
        $personal=strlen($identifier)===11;
        if ($personal && $identifier!=='11111111111') {
            $invalid=false;
            (new \App\Rules\TurkishIdentityNumber)->validate('identifier',$identifier,function () use (&$invalid) { $invalid=true; });
            if ($invalid) throw new DomainException('Geçersiz taraf T.C. kimlik numarası.');
        }
        $party=$this->node($this->node($root,'cac',$type),'cac','Party');
        $this->node($this->node($party,'cac','PartyIdentification'),'cbc','ID',$identifier)->setAttribute('schemeID',$personal?'TCKN':'VKN');
        if (!$personal) $this->node($this->node($party,'cac','PartyName'),'cbc','Name',$this->field($data,'name'));
        $address=$this->node($party,'cac','PostalAddress');
        $this->node($address,'cbc','StreetName',$this->field($data,'address',1000));
        $this->node($address,'cbc','CitySubdivisionName',$this->field($data,'district'));
        $this->node($address,'cbc','CityName',$this->field($data,'city'));
        $country=$this->node($address,'cac','Country');
        $this->node($country,'cbc','IdentificationCode','TR');
        $this->node($country,'cbc','Name','Türkiye');
        if (!$personal || isset($data['tax_office'])) {
            $scheme=$this->node($this->node($party,'cac','PartyTaxScheme'),'cac','TaxScheme');
            $this->node($scheme,'cbc','Name',$this->field($data,'tax_office'));
        }
        if (isset($data['email'])) {
            $email=$this->field($data,'email',254);
            if (!filter_var($email,FILTER_VALIDATE_EMAIL)) throw new DomainException('Alıcı e-posta adresi geçersiz.');
            $this->node($this->node($party,'cac','Contact'),'cbc','ElectronicMail',$email);
        }
        if ($personal) {
            $person=$this->node($party,'cac','Person');
            $this->node($person,'cbc','FirstName',$this->field($data,'first_name'));
            $this->node($person,'cbc','FamilyName',$this->field($data,'last_name'));
        }
    }

    /** Nine decimal TRY unit price, using integer division rather than float.
     * At the supported quantity cap this preserves rounded line cents. */
    private function netUnitPrice(int $net,int $qty): string
    {
        if ($net<0 || $net>1_000_000_000_000 || $qty<1 || $qty>1_000_000) throw new DomainException('Geçersiz satır miktarı veya tutarı.');
        $wholeCents=intdiv($net,$qty);
        $fraction=intdiv(($net%$qty)*10_000_000+intdiv($qty,2),$qty);
        if ($fraction===10_000_000) { $wholeCents++; $fraction=0; }
        return intdiv($wholeCents,100).'.'.str_pad((string)($wholeCents%100),2,'0',STR_PAD_LEFT).str_pad((string)$fraction,7,'0',STR_PAD_LEFT);
    }

    public function render(InvoicePreparation $draft,array $seller,array $buyer,string $profile,string $issueDate,string $orderNumber,string $orderDate): string
    {
        if (!in_array($profile,['TEMELFATURA','TICARIFATURA'],true)) throw new DomainException('Bu yöntem yalnızca temel/ticari satış faturası adayını destekler.');
        return $this->document($draft,$seller,$buyer,$profile,$issueDate,$orderNumber,$orderDate,[],false);
    }

    /**
     * Internet-sale archive candidate only. The caller must explicitly attest
     * to a synthetic test or transaction-specific anonymous consumer eligibility.
     * This is not a fiscal policy decision, and there is no submission route.
     */
    public function archive(InvoicePreparation $draft,array $seller,array $buyer,string $issueDate,string $orderNumber,string $orderDate,string $website,string $paymentMethod,?string $intermediary,\DateTimeInterface $paidAt,\DateTimeInterface $dispatchedAt,string $carrierVkn,string $carrierTitle,string $series,bool $anonymousArchivePermitted=false): array
    {
        if (!preg_match('/^[A-Z0-9]{3}$/D',$series) || in_array($series,['GIB','ABC'],true)) throw new DomainException('İnternet satışına özel belge serisi seçilmeli.');
        $this->field($buyer,'email',254);
        $header=(new EdmInternetSaleDetails)->build($website,$paymentMethod,$intermediary,$paidAt,$dispatchedAt,$carrierVkn,$carrierTitle);
        $tz=new \DateTimeZone('Europe/Istanbul');
        $paidLocal=\DateTimeImmutable::createFromInterface($paidAt)->setTimezone($tz);
        $dispatchLocal=\DateTimeImmutable::createFromInterface($dispatchedAt)->setTimezone($tz);
        if ($paidLocal->format('Y-m-d')<$this->date($orderDate) || $paidLocal->format('Y-m-d')>$this->date($issueDate)) throw new DomainException('Ödeme tarihi sipariş ve belge tarihleriyle uyuşmuyor.');
        // Physical shipment data must be actual, not an invented future date.
        // This preliminary flow does not support invoicing before dispatch.
        if ($dispatchLocal->format('Y-m-d')>$issueDate) throw new DomainException('Bu teknik akışta sevk tarihi belge tarihinden sonra olamaz.');
        $notes=['İnternet satışı teknik adayı.', 'Web adresi: '.$website,
            'Ödeme şekli: '.str_replace('/ ','/',$paymentMethod),
            'Ödeme tarihi: '.$paidLocal->format('Y-m-d'),
            'Sevk tarihi: '.$dispatchLocal->format('Y-m-d'),
            'Taşıyıcı: '.$this->field(['carrier'=>$carrierTitle],'carrier').' (VKN '.$carrierVkn.')'];
        if ($intermediary!==null) $notes[]='Ödeme aracısı: '.$this->field(['intermediary'=>$intermediary],'intermediary');
        $xml=$this->document($draft,$seller,$buyer,'EARSIVFATURA',$issueDate,$orderNumber,$orderDate,$notes,$anonymousArchivePermitted);
        // Series choice remains local metadata, not an allocated invoice ID.
        // EDM SOAP serialization and actual series membership checks are later gates.
        return ['xml'=>$xml,'header'=>$header,'requested_series'=>$series,'submission_allowed'=>false];
    }

    /**
     * EDM C# pre-signing shape, offline only. Empty extension content is
     * explicitly distinct from the GIB XSD candidate and is NOT approved
     * for submission. No allocation, network, route, or signing.
     */
    public function rehearseEdmDraft(InvoicePreparation $draft,array $seller,array $buyer,string $profile,string $issueDate,string $orderNumber,string $orderDate): array
    {
        if (!in_array($profile,['TEMELFATURA','TICARIFATURA'],true)) throw new DomainException('EDM ön imzalama provası yalnızca e-Fatura içindir.');
        $xml=$this->document($draft,$seller,$buyer,$profile,$issueDate,$orderNumber,$orderDate,[],false,true);
        return ['xml'=>$xml,'sha256'=>hash('sha256',$xml),'submission_allowed'=>false,
            'signature_verified'=>false,'official_validation_confirmed'=>false];
    }

    /** Separate controlled synthetic archive draft, not an issued document. */
    public function rehearseArchiveDraft(InvoicePreparation $draft,array $seller,array $buyer,string $date,string $website,string $series): array
    {
        if ($buyer['identifier']!=='11111111111'||$buyer['email']!=='newtic-archive-test@example.invalid'
            || $seller['identifier']!==EdmSandboxSmokeFixture::IDENTIFIER
            || !preg_match('/^[A-Z0-9]{3}$/D',$series)||in_array($series,['ABC','GIB'],true))
            throw new DomainException('ARCHIVE_FIXTURE_SCOPE');
        $when=new \DateTimeImmutable($date.'T12:00:00+03:00');
        $header=(new EdmInternetSaleDetails)->build($website,'EFT/HAVALE',null,$when,$when,
            EdmSandboxSmokeFixture::IDENTIFIER,'Sentetik test taşıyıcısı (EDM test kimliği)');
        $xml=$this->document($draft,$seller,$buyer,'EARSIVFATURA',$date,'NEWTIC-ARCHIVE-SMOKE-01',$date,
            ['NEWTIC sentetik entegrasyon testi','Web adresi: '.$website,'Ödeme şekli: EFT/HAVALE','Ödeme tarihi: '.$date,'Sevk tarihi: '.$date,'Taşıyıcı: Sentetik test taşıyıcısı'],true,true);
        return ['xml'=>$xml,'header'=>$header,'series'=>$series];
    }

    private function document(InvoicePreparation $draft,array $seller,array $buyer,string $profile,string $issueDate,string $orderNumber,string $orderDate,array $notes,bool $anonymousArchivePermitted,bool $edmRehearsal=false): string
    {
        if (!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iD',$draft->uuid ?? '')) throw new DomainException('Taslak ETTN geçersiz.');
        if ($this->date($orderDate)>$this->date($issueDate)) throw new DomainException('Sipariş tarihi belge tarihinden sonra olamaz.');
        $orderNumber=$this->field(['order'=>$orderNumber],'order',100);
        $parts=new DOMDocument();
        if (!$parts->loadXML($this->components->render($draft),LIBXML_NONET)) throw new DomainException('Hesap bileşenleri okunamadı.');
        $doc=new DOMDocument('1.0','UTF-8');
        $doc->formatOutput=true;
        $root=$doc->appendChild($doc->createElementNS(self::INV,'Invoice'));
        if ($edmRehearsal) EdmUblNamespace::declare($root);
        // The Turkish invoice XSD requires UBLExtensions and Signature.
        // This explicit non-fiscal marker is NOT a cryptographic signature.
        $extensions=$root->appendChild($doc->createElementNS(self::EXT,'ext:UBLExtensions'));
        $extension=$extensions->appendChild($doc->createElementNS(self::EXT,'ext:UBLExtension'));
        $content=$extension->appendChild($doc->createElementNS(self::EXT,'ext:ExtensionContent'));
        if (!$edmRehearsal) {
            $marker=$content->appendChild($doc->createElementNS(self::UNSIGNED,'nwt:UnsignedCandidate'));
            $marker->appendChild($doc->createTextNode('NOT_FOR_SUBMISSION'));
        }
        $this->node($root,'cbc','UBLVersionID','2.1');
        $this->node($root,'cbc','CustomizationID','TR1.2');
        $this->node($root,'cbc','ProfileID',$profile);
        $this->node($root,'cbc','ID',self::EDM_SERIAL_SENTINEL);
        $this->node($root,'cbc','CopyIndicator','false');
        $this->node($root,'cbc','UUID',$draft->uuid);
        $this->node($root,'cbc','IssueDate',$issueDate);
        $this->node($root,'cbc','InvoiceTypeCode','SATIS');
        if (!$edmRehearsal) $this->node($root,'cbc','Note','NEWTIC TEKNİK TEST ADAYI — RESMÎ BELGE DEĞİLDİR, GÖNDERİLMEZ.');
        foreach ($notes as $note) $this->node($root,'cbc','Note',$note);
        $this->node($root,'cbc','DocumentCurrencyCode','TRY');
        $this->node($root,'cbc','LineCountNumeric',(string)count($draft->amounts['lines']));
        $reference=$this->node($root,'cac','OrderReference');
        $this->node($reference,'cbc','ID',$orderNumber);
        $this->node($reference,'cbc','IssueDate',$orderDate);
        $this->party($root,'AccountingSupplierParty',$seller);
        // Build the required structural signature reference using validated
        // seller fields, with an intentionally unresolved unsigned-only URI.
        // EDM signing is not implemented; never send this test candidate.
        $supplier=$root->lastChild;
        $signature=$this->node($root,'cac','Signature');
        $this->node($signature,'cbc','ID',$this->field($seller,'identifier',11))->setAttribute('schemeID','VKN_TCKN');
        $signatory=$this->node($signature,'cac','SignatoryParty');
        foreach ($supplier->firstChild->childNodes as $field) {
            if ($field instanceof DOMElement) $signatory->appendChild($field->cloneNode(true));
        }
        $attachment=$this->node($signature,'cac','DigitalSignatureAttachment');
        $reference=$this->node($attachment,'cac','ExternalReference');
        $this->node($reference,'cbc','URI',$edmRehearsal?'#Signature_'.self::EDM_SERIAL_SENTINEL:'#NEWTIC_UNSIGNED_TEST_ONLY');
        $root->insertBefore($signature,$supplier);
        $this->party($root,'AccountingCustomerParty',$buyer,$profile==='EARSIVFATURA' && $anonymousArchivePermitted);
        $index=0;
        foreach ($parts->documentElement->childNodes as $node) {
            if (!$node instanceof DOMElement || $node->namespaceURI!==self::CAC) continue;
            if (!in_array($node->localName,['TaxTotal','LegalMonetaryTotal','InvoiceLine'],true)) continue;
            $import=$root->appendChild($doc->importNode($node,true));
            if ($node->localName==='InvoiceLine') {
                $line=$draft->amounts['lines'][$index++];
                $price=$this->node($import,'cac','Price');
                $this->node($price,'cbc','PriceAmount',$this->netUnitPrice($line['net_cents'],$line['quantity']))->setAttribute('currencyID','TRY');
            }
        }
        if ($index!==count($draft->amounts['lines'])) throw new DomainException('Belge satırları uyuşmuyor.');
        $xml=$doc->saveXML();
        if ($xml===false) throw new DomainException('Fatura XML oluşturulamadı.');
        if ($edmRehearsal) {
            EdmUblNamespace::assertTransport($xml);
            if ($profile==='EARSIVFATURA') (new UblCandidatePreflight)->validateArchiveProviderDraft($xml,$draft->amounts,$draft->uuid);
            else (new UblCandidatePreflight)->validateProviderDraft($xml,$draft->amounts,$draft->uuid,$profile);
        }
        else (new UblCandidatePreflight)->validate($xml,$draft->amounts,$draft->uuid,$profile,$anonymousArchivePermitted);
        return $xml;
    }
}
